import {WAYGLASS_OBJECT,RARE_MAKO,hasWayglass,ownsRelic,isMakoAttuned,equipRareMako} from './wayglass-model.js?v=5.11.0';
export function appendWayglassBag(panel,state,{onOpen,onGrid}){if(!hasWayglass(state))return;const card=document.createElement('article');card.className='wayglass-kit-card';const art=document.createElement('img');art.src=new URL('./art/wayglass/wayglass.svg',import.meta.url);art.alt='Rook’s folding brass Wayglass';const h=document.createElement('h3');h.textContent=WAYGLASS_OBJECT.name+' · carried tool';const p=document.createElement('p');p.textContent=WAYGLASS_OBJECT.description;const button=document.createElement('button');button.textContent='Unfold the Wayglass';button.onclick=onOpen;card.append(art,h,p,button);for(const r of RARE_MAKO.filter(r=>ownsRelic(state,r.id))){const row=document.createElement('p');row.textContent=r.icon+' '+r.name+' · '+r.core.toUpperCase()+' Mako — '+r.effect;card.append(row);}if(RARE_MAKO.some(r=>ownsRelic(state,r.id))){const b=document.createElement('button');b.textContent='Attune recovered Mako on Resonance Paths';b.onclick=onGrid;card.append(b);}panel.append(card);}
export function appendRareMakoSlot(panel,state,id,index,{onChange}){const h=state.heroes[id],slot=h.loadout[index];const found=RARE_MAKO.filter(r=>ownsRelic(state,r.id));if(!found.length)return;const label=document.createElement('label');label.className='rare-mako-slot';label.append(document.createTextNode('Rare Mako in link '+(index+1)+' '));const select=document.createElement('select');select.setAttribute('aria-label',h.name+' rare Mako in link '+(index+1));select.add(new Option('Ordinary core pattern',''));for(const r of found){const ready=isMakoAttuned(state,id,r.id)&&state.cores.includes(r.core),o=new Option(r.name+(ready?' · '+r.effect:' · attune on Resonance Paths first'),r.id);o.disabled=!ready;select.add(o);}select.value=slot.makoId||'';select.onchange=()=>{if(!select.value)delete slot.makoId;else if(!equipRareMako(state,id,index,select.value))return;onChange();};label.append(select);panel.append(label);}
